class Solution {
    public int trapRainWater(int[][] heightMap) {
        int m = heightMap.length, n = heightMap[0].length;
        if (m < 3 || n < 3) return 0;
        java.util.PriorityQueue<int[]> pq = new java.util.PriorityQueue<>((a, b) -> a[2] - b[2]);
        boolean[][] visited = new boolean[m][n];
        for (int i = 0; i < m; i++) {
            pq.offer(new int[]{i, 0, heightMap[i][0]}); visited[i][0] = true;
            pq.offer(new int[]{i, n - 1, heightMap[i][n - 1]}); visited[i][n - 1] = true;
        }
        for (int j = 1; j < n - 1; j++) {
            pq.offer(new int[]{0, j, heightMap[0][j]}); visited[0][j] = true;
            pq.offer(new int[]{m - 1, j, heightMap[m - 1][j]}); visited[m - 1][j] = true;
        }
        int[][] dirs = {{0,1},{0,-1},{1,0},{-1,0}};
        int water = 0;
        while (!pq.isEmpty()) {
            int[] cell = pq.poll();
            for (int[] d : dirs) {
                int nr = cell[0] + d[0], nc = cell[1] + d[1];
                if (nr >= 0 && nr < m && nc >= 0 && nc < n && !visited[nr][nc]) {
                    visited[nr][nc] = true;
                    water += Math.max(0, cell[2] - heightMap[nr][nc]);
                    pq.offer(new int[]{nr, nc, Math.max(cell[2], heightMap[nr][nc])});
                }
            }
        }
        return water;
    }
}

import java.util.*;

class Solution {
    public int trapRainWater(int[][] heightMap) {
        int m = heightMap.length, n = heightMap[0].length;
        if (m < 3 || n < 3) return 0;
        int[][] water = new int[m][n];
        int maxH = 0;
        for (int[] row : heightMap) for (int h : row) maxH = Math.max(maxH, h);
        Queue<int[]> queue = new LinkedList<>();
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (i == 0 || i == m - 1 || j == 0 || j == n - 1) {
                    water[i][j] = heightMap[i][j];
                    queue.offer(new int[]{i, j});
                } else {
                    water[i][j] = maxH;
                }
            }
        }
        int[][] dirs = {{0,1},{0,-1},{1,0},{-1,0}};
        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            int r = cell[0], c = cell[1];
            for (int[] d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr > 0 && nr < m - 1 && nc > 0 && nc < n - 1) {
                    int newWater = Math.max(heightMap[nr][nc], water[r][c]);
                    if (newWater < water[nr][nc]) {
                        water[nr][nc] = newWater;
                        queue.offer(new int[]{nr, nc});
                    }
                }
            }
        }
        int total = 0;
        for (int i = 1; i < m - 1; i++) {
            for (int j = 1; j < n - 1; j++) {
                total += water[i][j] - heightMap[i][j];
            }
        }
        return total;
    }
}
